mapper.select:
SELECT COUNT(*)
FROM recommendation_exposure_log
WHERE created_at >= #{since}
AND category = #{category}

SELECT COUNT(DISTINCT user_id)
FROM recommendation_exposure_log
WHERE created_at >= #{since}
  AND user_id IS NOT NULL
AND category = #{category}

SELECT COUNT(DISTINCT item_id)
FROM recommendation_exposure_log
WHERE created_at >= #{since}
AND category = #{category}

SELECT LEAST(FLOOR(score * 10), 10) AS bucket, COUNT(*) AS cnt
FROM recommendation_exposure_log
WHERE created_at >= #{since}
AND category = #{category}
GROUP BY bucket
ORDER BY bucket

SELECT item_id AS itemId, COUNT(*) AS exposures
FROM recommendation_exposure_log
WHERE created_at >= #{since}
AND category = #{category}
GROUP BY item_id
ORDER BY exposures DESC, item_id ASC
LIMIT #{limit}

mapper.sql:
INNER JOIN recommendation_exposure_log l
    ON l.user_id = r.user_id
   AND l.item_id = r.item_id
   AND l.category = #{itemType}
   AND r.create_time >= l.created_at
   AND r.create_time <= DATE_ADD(l.created_at, INTERVAL #{attributionHours} HOUR)
WHERE r.item_type = #{itemType}
  AND r.create_time >= #{since}
